function currentUsageQuestion(){const w=wordById(currentItem()?.wordId),entry=pilotById.get(w?.id);if(entry)return entry.exercises.find(q=>q.id===state.session?.questionId)||null;const q=customContext(w);return q?{id:'custom-context-'+w.id,...q}:null;}
