function usageAudioHTML(q){const spec=contextAudioSpec(q);return `<div class="context-sentence-audio"><button class="audio-button" data-action="context-audio" ${spec.text?'':'disabled'}>◖)) 朗读例句</button> ${button('停止','context-stop','text-button')}<p class="audio-source">${spec.file?'Kokoro · '+(spec.voice==='af_heart'?'女声':'男声')+' · 美音例句':'设备英语例句朗读 · 音色由设备决定'}</p><p class="inline-note">只读题目例句，空格处停顿；不会读选项或补入答案。</p><p id="context-speech-notice" class="inline-note" role="status"></p></div>`;}
function playContextSentence(){const spec=contextAudioSpec(currentUsageQuestion());if(!spec.text){stopAudio();toast('当前没有可朗读的例句。');return;}playPracticeText(spec.text,$('#context-speech-notice'),{file:spec.file});}
function correctionKey(){const s=state.session,r=s?.remediation;return r?`${s.id}:${s.index}:${r.step}:${r.attempts}`:null;}
function playCorrectionWord({device=false,automatic=false}={}){const s=state.session,r=s?.remediation;if(!r||r.paused||r.done)return;const key=correctionKey(),w=wordById(r.wordId),entry=recordedAudio.get(r.wordId);stopAudio();correctionAutoKey=key;if(r.step>0&&$('#correction-submit'))$('#correction-submit').disabled=true;const active=()=>view==='session'&&correctionKey()===key&&!state.session?.remediation?.paused;const status=()=>$('#correction-audio-status');const update=text=>{if(active()&&status())status().textContent=text;};const options={retry:!automatic,onLoading:update,onStart:()=>update(entry&&!device?'正在播放Kokoro整词美音。':'正在使用设备英语声音朗读整词。'),onComplete:()=>{if(!active())return;correctionListenReady=true;update('整词播放完成，可以核对拼写。');const b=$('#correction-submit');if(b&&!state.session.remediation.feedback)b.disabled=false;},onError:message=>{if(!active())return;update(message);if(status()){const retry=document.createElement('button');retry.className='text-button';retry.textContent='重试整词朗读';retry.onclick=()=>playCorrectionWord();status().append(document.createElement('br'),retry);if(entry&&!device){const fallback=document.createElement('button');fallback.className='text-button';fallback.textContent='改用设备整词朗读';fallback.onclick=()=>playCorrectionWord({device:true});status().append(document.createElement('br'),fallback);}}}};if(entry&&!device)player.playFile(new URL('../'+entry.file,import.meta.url).href,options);else player.playSpeech(w.english,options);}
function playCorrectionSyllable(index){const r=state.session?.remediation;if(!r||r.paused||r.done||r.step!==0)return;const entry=SYLLABLES.entries.find(e=>e.wordId===r.wordId&&e.text===wordById(r.wordId)?.english),syllable=entry?.syllables[index];if(!syllable?.audioFile)return;const key=correctionKey();stopAudio();const update=text=>{if(correctionKey()===key&&$('#correction-audio-status'))$('#correction-audio-status').textContent=text;};player.playFile(new URL('../'+syllable.audioFile,import.meta.url).href,{retry:true,onLoading:update,onStart:()=>update(`正在分读第${index+1}个音节（合成声音）。`),onComplete:()=>update('分读结束，可再听整词连贯读法。'),onError:message=>update(message+' 可重试本音节或听整词；不会用拼写字母朗读冒充音节。')});}
