function audioHTML(w){const e=recordedAudio.get(w.id),label=e?`Kokoro · ${e.voice==='af_heart'?'女声':'男声'} · 美音`:'设备合成朗读';return `<button class="audio-button" data-action="audio">◖)) 整词朗读</button><p class="audio-source">${label}${e?'':' · 此词暂无预生成音频'}</p>${['listening','dictation'].includes(currentItem()?.skill)?'<p class="audio-shortcut">每题自动播放 · 单独按下并松开 Ctrl 可重播</p>':''}<div id="speech-notice" class="notice" hidden role="status"></div>`;}
