function phonicsHTML(w){const e=pilotById.get(w.id);if(!e&&w.textbookIpa)return `<div class="phonics"><h3>教材音标 · 英式记号</h3><div class="ipa">${esc(w.textbookIpa)}</div>${w.textbookAlternatives?.length?`<p>教材列出的其他形式：${w.textbookAlternatives.map(esc).join("、")}。听写仍以当前朗读的目标词为准。</p>`:""}<p>按教材补充词表记录；整词合成朗读采用美音，二者可能不同。读音音节与拼写分块尚未核对，不自动猜分。</p></div>`;if(!e)return '<div class="phonics"><h3>拼读资料待补充</h3><p>此词尚无核对后的音节、音标与类型数据。可继续整词学习；不会用猜测切分冒充准确拼读。</p></div>';return `<div class="phonics"><div class="panel-heading"><h3>先看拼读 · 美音试学</h3><span class="badge blue">20词核对包</span></div><div class="ipa">${esc(e.pronunciation.ipa)}</div><p>${e.pronunciation.monosyllabic?'单音节':`${e.pronunciation.syllableCount}个读音音节 · 第${e.pronunciation.primaryStressSyllable}音节重读`}：${e.pronunciation.syllables.map(s=>`${s.stress==='primary'?'ˈ':''}${esc(s.ipa)}`).join(' · ')}</p><div class="phonics-chunks">${e.teaching.orthographicChunks.map(c=>`<span class="chunk ${esc(c.type)}"><strong>${esc(c.text)}</strong><small>${esc(typeById.get(c.type)?.labelZh||c.type)}</small></span>`).join('')}</div><p>上方彩色块是拼写教学分块；音标中的点号才是所选词典读音标记。</p><details><summary>展开拼读讲解</summary><ul>${e.teaching.orthographicChunks.map(c=>`<li><strong>${esc(c.text)}</strong>：${esc(c.explanationZh)}</li>`).join('')}</ul><p>${esc(e.pronunciation.notesZh)}</p><a href="${esc(PILOT.sources.find(x=>x.id===e.pronunciation.sourceIds[0])?.url)}" target="_blank" rel="noopener">词典读音来源</a></details><p class="inline-note" style="margin-top:12px">分音节录音暂不可用。整词可单独朗读；不把完整单词或拼写块冒充音节音频。</p></div>`;}
