function relatedPhraseGroups(entry){const core=entry.english.toLowerCase().replace(/^be /,'').replace(/(?: doing something| to do something| somebody| something| someone)$/,'').trim();if(core.length<5)return [];return ['context','reading','cloze'].map(module=>({module,ids:ADAPTIVE_BANK.questions.filter(q=>q.module===module&&((q.completedPassage||q.passage||q.context||q.prompt||'').replace(/_{2,}/g,q.answer||'').toLowerCase().includes(core))).map(q=>q.id)})).filter(g=>g.ids.length);}
phraseRuntime=createPhraseUI({document,root:phraseRoot,bank:PHRASE_BANK,audio:PHRASE_AUDIO,prepare:file=>player.prefetchFile(file).catch(()=>{}),esc,save:savePhrase,onRender:render,stopAudio,playFile:(file,options)=>player.playFile(file,options),playSpeech:(text,options)=>player.playSpeech(text,options),onFocus:element=>answerFocus.focusEditor(element),onWordTracker:()=>go('track'),relatedFor:relatedPhraseGroups,onRelated:(module,ids)=>{phraseRelatedParent=true;const existing=state.adaptive?.modules?.[module]?.session;if(existing&&!existing.complete){phraseRelatedFilter=null;toast('该模块已有未完成的一组，先继续已保存练习。');}else phraseRelatedFilter={module,ids};go(module);},now});
